with base as (select * from order_items where product_id is not null), summary as (select case when unit_price >= 350 then 'high' when unit_price >= 110 then 'mid' else 'low' end as unit_price_bucket, max(quantity) as max_quantity, sum(unit_price * quantity) as revenue from base group by case when unit_price >= 350 then 'high' when unit_price >= 110 then 'mid' else 'low' end) select unit_price_bucket, revenue from summary where revenue > 37;
